WITH recent_inventory AS (SELECT *, ADD_MONTHS(last_restock, 12) AS last_restock_plus_months FROM inventory WHERE last_restock <= '2024-05-01'), agg AS (SELECT QUARTER(last_restock_plus_months) AS last_restock_plus_months_quarter, COUNT(*) AS num_inventory, MAX(quantity) - MIN(quantity) AS quantity_range FROM recent_inventory GROUP BY QUARTER(last_restock_plus_months)) SELECT last_restock_plus_months_quarter, num_inventory, quantity_range FROM agg WHERE quantity_range > 50;
